-- Name: Departure sort % - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH target_routes AS ( /* Optimization 1: Moving massive IN clause to a CTE to prevent internal engine errors */ SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (733, 807), (462, 130), (807, 733), (313, 979), (979, 313), (130, 444), (309, 130), (130, 571), (122, 602), (602, 122), (141, 126), (646, 130), (74706, 74820), (126, 141), (233, 123), (551, 472), (571, 130), (733, 1290), (551, 473), (473, 551), (1290, 733), (122, 129), (472, 551), (130, 79546), (71929, 141), (124, 125), (90883, 74701), (470, 551), (236, 122), (74701, 90883), (125, 124), (1443, 807), (807, 70015), (807, 1443), (313, 1001), (71756, 123), (807, 1290), (129, 122), (313, 94152), (467, 123), (979, 1001), (244, 122), (123, 467), (1001, 313), (293, 122), (443, 979), (979, 443), (455, 123), (1001, 81826), (1001, 979), (123, 455), (141, 216), (94152, 313), (602, 141), (201668, 74706), (443, 70024), (70024, 83760), (1290, 70015) ) AS t(s, d) ), dep_sort_sess AS ( SELECT DISTINCT filter_applied, mri_session_id, CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, "__time")) AS DATE) AS doi, doj_doi -- DISTINCT train_position FROM "user_interaction"."ui_ux_events" WHERE 1=1 AND __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' AND header_country = 'IND' AND filter_type IS NOT NULL AND event_group = 'srp_screen_load' AND train_position = 'DEP_TIME' AND header_bu = 'BUS' ), srp_deduped AS ( SELECT CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, s."__time")) AS DATE) AS doi, s.mri_session_id, s.route_id, s.rb_user_id, UPPER(s.user_type) user_type, s.os, s.channel, s.src_id, s.dest_id, CAST(date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) AS VARCHAR) AS doj_doi, -- rm.region, CASE WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 AND HOUR(DATE_ADD('minute', 330, s."__time")) >= 17 THEN '0. LMB Same Day' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 THEN '0. non-LMB Same Day' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'NA' END AS search_day, CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL THEN 'Target SDs' ELSE 'non-Target SDs' END AS target_route -- , -- CASE -- WHEN ev.is_clicked = 1 THEN 'Card Interacted sessions' -- WHEN ev.is_viewed = 1 THEN 'Viewed but not interacted sessions' -- ELSE 'Regular session' -- END AS section_interaction, -- CASE WHEN ev.is_contextual = 1 THEN 'contextual_filtered_sessions' ELSE 'non-contextual_filtered_sessions' END AS contextual_filter_interaction FROM "user_interaction"."search_route_details" s INNER JOIN target_routes tr ON s.src_id = tr.src_id AND s.dest_id = tr.dest_id /* Only for the target routes */ -- LEFT JOIN target_routes tr ON s.src_id = tr.src_id AND s.dest_id = tr.dest_id /* All routes with identifier for the target routes */ -- LEFT JOIN "lis"."config_locations" rm ON rm.id = s.src_id WHERE s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-31 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.country = 'IND' AND s.status = 200 ) SELECT CASE WHEN s.os IS NULL THEN s.channel ELSE s.os END AS saleschannel, s.user_type, s.search_day, COUNT(DISTINCT s.mri_session_id) overall_srp_sessions, COUNT(DISTINCT CASE WHEN f.mri_session_id IS NOT NULL THEN s.mri_session_id END) AS dep_sort_applied_sessions FROM srp_deduped s LEFT JOIN dep_sort_sess f ON f.mri_session_id = s.mri_session_id AND f.doi = s.doi AND f.doj_doi = s.doj_doi GROUP BY 1, 2, 3 ORDER BY 1, 3, 2 DESC, 4 DESC
